class EMALongStrategy(Strategy):
    def on_bar(self, ctx):
        # Ensure enough data for EMA calculations
        hist = ctx.history()
        if len(hist) < 26:
            return
        close = hist['close']
        ema12 = close.ewm(span=12, adjust=False).mean().iloc[-1]
        ema26 = close.ewm(span=26, adjust=False).mean().iloc[-1]
        position = ctx.position()
        if ema12 > ema26:
            # Enter long if not already in a position
            if position == 0:
                ctx.order_target_percent(0.95)
        else:
            # Exit any existing position
            if position != 0:
                ctx.order_target_percent(0)

