class MyStrategy(Strategy):
    def on_bar(self, ctx):
        # Need at least 4 bars to evaluate entry (3 prior closes) and exit conditions
        if len(ctx.history()) < 4:
            return
        position = ctx.position()
        # Get the most recent 4 closes (including current bar)
        hist = ctx.history(length=4)
        closes = hist['close']
        # Entry condition: flat and three consecutive lower closes (t-3 > t-2 > t-1)
        if position == 0:
            prev3 = closes.iloc[-4:-1]  # closes at t-3, t-2, t-1
            if prev3.iloc[0] > prev3.iloc[1] > prev3.iloc[2]:
                ctx.order_target_percent(0.95)
                return
        # Exit condition: long and current close > previous close
        if position > 0:
            if closes.iloc[-1] > closes.iloc[-2]:
                ctx.close_position()

