class DonchianBreakoutStrategy(Strategy):
    def on_bar(self, ctx):
        # Need at least 21 bars of history (including current)
        hist = ctx.history()
        if len(hist) < 21:
            return
        position = ctx.position()
        # Highest high of previous 20 bars (excluding today)
        prev_20_high = hist.iloc[-21:-1]['high'].max()
        # Lowest low of previous 10 bars (excluding today)
        prev_10_low = hist.iloc[-11:-1]['low'].min()
        price = ctx.price()
        if position == 0:
            if price > prev_20_high:
                ctx.order_target_percent(0.95)
        elif position > 0:
            if price < prev_10_low:
                ctx.close_position()

