class BreakoutStopStrategy(Strategy):
    def init(self, ctx):
        # Index (in history) of the bar where we first observed a long position.
        self.entry_bar_index = None

    def on_bar(self, ctx):
        hist = ctx.history()
        # Need at least 20 bars to compute the highest high.
        if len(hist) < 20:
            return

        position = ctx.position()

        if position == 0:
            # Flat: cancel any pending entry orders and possibly re‑enter.
            self.entry_bar_index = None
            ctx.cancel_orders()
            # Highest high of the last 20 bars (including today).
            stop_price = hist['high'].iloc[-20:].max()
            # Number of shares: 95% of equity divided by today's close price.
            qty = int(0.95 * ctx.equity / ctx.price())
            if qty > 0:
                ctx.buy(qty, stop_price=stop_price)
        else:
            # We are long.
            if self.entry_bar_index is None:
                # Record the bar where we first see the long position.
                self.entry_bar_index = len(hist) - 1
            else:
                # Number of bars elapsed since the entry bar (the entry bar counts as 0).
                elapsed = (len(hist) - 1) - self.entry_bar_index
                if elapsed >= 10:
                    ctx.close_position()
                    self.entry_bar_index = None

