class TurnOfMonthStrategy(backtester.Strategy):
    def init(self, ctx):
        # Track current month and bar count within the month
        self.current_year = None
        self.current_month = None
        self.bar_of_month = 0

    def on_bar(self, ctx):
        # Determine if we are on a new month
        ts = ctx.timestamp
        year = ts.year
        month = ts.month
        if self.current_year != year or self.current_month != month:
            # New month starts
            self.current_year = year
            self.current_month = month
            self.bar_of_month = 1
        else:
            self.bar_of_month += 1

        # First bar of the month: enter if flat
        if self.bar_of_month == 1:
            if ctx.position() == 0:
                ctx.order_target_percent(0.95)
        # Tenth bar of the month: exit if long
        elif self.bar_of_month == 10:
            if ctx.position() > 0:
                ctx.close_position()

