        dow = ctx.timestamp.weekday()
        pos = ctx.position()
        if dow == 4:  # Friday
            if pos == 0:
                ctx.order_target_percent(0.95)
        elif dow == 0:  # Monday
            if pos > 0:
                ctx.close_position()

