class EqualWeightRebalance(Strategy):
    def on_bar(self, ctx):
        # Ensure there are symbols
        if not ctx.symbols:
            return
        # Use first symbol to get bar count
        first_sym = ctx.symbols[0]
        hist = ctx.history(symbol=first_sym)
        if len(hist) == 0:
            return
        # Rebalance on first bar and every 20 bars thereafter (bars 1,21,41,...)
        if (len(hist) - 1) % 20 == 0:
            for sym in ctx.symbols:
                ctx.order_target_percent(0.30, symbol=sym)

