class BetterAssetStrategy(Strategy):
    def on_bar(self, ctx):
        # Number of trading days in roughly three months (approx 21 days per month)
        window = 63
        # Ensure sufficient history for both symbols
        for sym in ctx.symbols:
            if len(ctx.history(symbol=sym, length=window)) < window:
                return
        # Calculate total return over the window for each symbol
        returns = {}
        for sym in ctx.symbols:
            hist = ctx.history(symbol=sym, length=window)
            start_price = hist['close'].iloc[0]
            end_price = hist['close'].iloc[-1]
            returns[sym] = (end_price / start_price) - 1
        # Identify the symbol with the higher return
        best_sym = max(returns, key=returns.get)
        # If the returns are effectively equal, do nothing
        vals = list(returns.values())
        if abs(vals[0] - vals[1]) < 1e-9:
            return
        # Allocate 100% of equity to the best-performing symbol and close the other
        ctx.order_target_percent(1.0, symbol=best_sym)
        for sym in ctx.symbols:
            if sym != best_sym:
                ctx.close_position(symbol=sym)

