class MAUpDownStrategy(Strategy):
    def on_bar(self, ctx):
        # Need at least 51 bars to compute current and previous 50-day MA
        hist = ctx.history()
        if len(hist) < 51:
            return
        # Compute 50-day moving average of close price
        ma_current = hist['close'].iloc[-50:].mean()
        ma_prev = hist['close'].iloc[-51:-1].mean()
        # If MA is increasing, go fully long; otherwise exit any long position
        if ma_current > ma_prev:
            # Ensure we are fully long (100% of equity)
            if ctx.position() <= 0:
                ctx.order_target_percent(1.0)
        else:
            # MA not increasing (down or flat) – close any long position
            if ctx.position() > 0:
                ctx.close_position()
